        ["OK"] = "ठीक है",
        ["Prince_zone1_1"] = "धन्यवाद! तुम नेक हो—बहुत कम लोग अपनों से अनजान व्यक्ति के लिए खड़े होते हैं। मुझे लगा मौत करीब है—ये लोग दया का मतलब नहीं जानते।",
        ["Prince_zone1_2"] = "मुझे कुछ ऐसा पता चला जो मुझे नहीं पता होना चाहिए था: मेरे सैनिक एक निश्चित हर्मिट के तहत निषिद्ध प्रथाओं का अध्ययन कर रहे हैं। वे मुझे गवाह के रूप में खत्म करना चाहते थे...",
        ["Prince_zone1_3"] = "मैं चीजों को स्पष्ट करने के लिए अपने सैनिकों की एक इकाई लेकर गया, लेकिन मुझे बंदी बना लिया गया। हालाँकि, किस्मत अभी भी मेरे साथ थी, और मैं भागने में सफल रहा।",
        ["Prince_zone2_1"] = "मेरे आदमी! उसे मेरी सेना के प्रमुख पद पर रखना एक गलती थी... यदि तुम्हारे पास अभी भी सम्मान का एक अंश है, तो हमें बताओ कि डाकुओं का शिविर कहाँ है!",
        ["Sensei_arc_outro"] = "समाप्त।",
        ["Sensei_zone1_1"] = "बहुत अधिक संयोग। किसी को हमारी यात्रा के बारे में पता था और उसने डाकुओं को चेतावनी दी थी। लेकिन हर्मिट इसमें कैसे शामिल है? हमें पता लगाने की जरूरत है। चलो!",
        ["Sensei_zone2_1"] = "तुम्हें शर्म आनी चाहिए! अपने सम्मान को सीधे बेच रहे हो! और किसलिए? क्या तुम्हें लगता है कि लोग एक गद्दार का अनुसरण करेंगे? क्या यह युवाओं के लिए एक अच्छा उदाहरण है?",
        ["Sensei_zone3_2"] = "मुझे जवाब दो: शोगुन उसे मृत क्यों देखना चाहता है, और तुम जिस जादुई स्फीयर की बात कर रहे थे वह क्या है?",
        ["Sensei_zone4_2"] = "हमें राजकुमार को विडो मिलने से पहले रोकना होगा... और स्फीयर...",
        ["Sensei_zone5_1"] = "मैं तुम्हारे साथ सहानुभूति रखता हूँ—सचमुच। लेकिन टूटा हुआ दिल एक बुरा सलाहकार है। कृपया समझें: तुम्हारी वजह से लोग पीड़ित हैं।",
        ["Sensei_zone6_2"] = "रुको! मेरे पास बहुत सारे सवाल हैं! तुम कौन हो? वहाँ क्या है, गेट्स के पीछे? मैं जानना चाहता हूँ...",
        ["Wasp_zone4_3"] = "रुको—मैंने तुम्हें कम आँका था, बूढ़े आदमी! मुझे डिलीवरी के लिए भुगतान किया गया था, लेकिन विडो के सम्मान के लिए लड़ने से मेरा कोई लेना-देना नहीं है। मैं तुम्हें उसके छिपने की जगह दिखाऊँगी!",
        ["Wasp_zone4_4"] = "विडो राजकुमार से प्यार करती थी, लेकिन उसने उसे ठुकरा दिया। फिर उसे एक नया खिलौना मिल गया: शोगुन। वह बुढ़िया अपने बदले के लिए उस मूर्ख सेनापति का इस्तेमाल कर रही है।",
        ["Wasp_zone4_5"] = "विडो पुरुषों पर शासन करना चाहती है और उन्हें एक-दूसरे के खिलाफ लड़वाना चाहती है। स्फीयर उसके चुने हुए व्यक्ति को महान... और उसके प्रति पूरी तरह से वफादार बना देगा।",
        ["Widow_zone5_3"] = "मेरे लिए वापस लौटने का कोई रास्ता नहीं है। मैं देख सकती हूँ कि तुम मदद करना चाहते हो, लेकिन बहुत देर हो चुकी है—राजकुमार पहले ही स्फीयर ले चुका है। शोगुन ने उसकी रक्षा करने की कोशिश की, लेकिन सब व्यर्थ रहा।",
        ["Widow_zone5_4"] = "ने राजकुमार को कभी इतना... उग्र नहीं देखा। उसकी आँखों से अंगारे बरस रहे थे! उसने सोचा कि उस जगह पर एक देशद्रोही को मौत के घाट उतारना मज़ेदार होगा जहाँ हम पहली बार मिले थे। मैं तुम्हें दिखाती हूँ...",
        ["characterAncient"] = "प्राचीन",
        ["characterSensei"] = "सेंसी",
    },
    hun = {
        ["Ancient_zone6_1"] = "Nem álmodsz. Megállítottam az időt, hogy visszavigyem a Szférát az árnyak közé. A jelenléte itt hiba volt – az Árnyak Kapujának instabilitása okozta.",
        ["Ancient_zone6_2"] = "A változás küszöbön áll, ember. Egyelőre aludj. Mikor felébredsz, senki sem fog emlékezni a tettedre. Így kell lennie. Egy napon majd megérted...",
        ["Butcher_zone3_3"] = "He-he! Nézd, ahogy a Herceg inába szállt a bátorság! Látnod kellett volna az arcod, öreg. Látod? Az új barátod egy gerinctelen hazug!",
        ["Butcher_zone3_4"] = "Tudom, hogy amint a Herceg kileheli a lelkét, a Sógun engem sem hagy életben. Csak egy eszköz vagyok – feláldozható. Szóval... segítek neked.",
        ["Butcher_zone3_5"] = "Egy bizonyos hölgy meggyőzte a Sógunt, hogy a trón jog szerint az övé. Megígérte neki a Szférát, s hogy hatalmas hadúrrá válik – mindezt cserébe azért, hogy a vazallusa lesz.",
        ["Butcher_zone3_6"] = "Menj a kikötőbe. A Sógun egy hajó érkezésére vár – arra, amelyik a Szférát hozza. Ez a Herceg utolsó esélye, hogy visszaszerezze a trónját.",
        ["Hermit_zone2_3"] = "Próbáld megérteni – a művészetünk a végéhez közeledik! A túléléshez változnia kell. Tudom, hogyan, és Sógun védelmet ígért cserébe az emberei kiképzéséért.",
        ["Hermit_zone2_4"] = "Mészáros a bandájával nem messze innen tanyázik. Ők raboltak el, uram. Menj – találd meg a válaszokat, amiket keresel.",
        ["NAME_BUTCHER"] = "HENTES",
        ["NAME_HERMIT"] = "REMETE",
        ["NAME_PRINCE"] = "HERCEG",
        ["NAME_WASP"] = "DARÁZS",
        ["NAME_WIDOW"] = "ÖZVEGY",
        ["OK"] = "OK",
        ["Prince_zone1_1"] = "Köszönöm! Nemes lélek vagy – kevesen állnának ki valakiért, akit nem is ismernek. Azt hittem, közel a halál – ezek az emberek nem ismernek irgalmat.",
        ["Prince_zone1_2"] = "Megtudtam valami olyasmit, amit nem lett volna szabad: a katonáim tiltott tanokat tanultak egy bizonyos Remeténél. Meg akartak szabadulni tőlem, mint tanútól...",
        ["Prince_zone1_3"] = "Elvittem hozzá egy egységnyi embert, hogy tisztázzuk a dolgokat, de fogságba estem. A szerencse azonban mellém állt, és sikerült elszöknöm.",
        ["Prince_zone2_1"] = "Az embereim! Hiba volt őt a hadseregem élére állítani... Ha maradt még bennetek akár egy pici becsület is, mondjátok meg, hol van a banditák tábora!",
        ["Sensei_arc_outro"] = "Vége.",
        ["Sensei_zone1_1"] = "Túl sok a véletlen egybeesés. Valaki tudott a látogatásunkról, és figyelmeztette a banditákat. De hogy jön a képbe a Remete? Ki kell derítenünk. Gyerünk!",
        ["Sensei_zone2_1"] = "Szégyelld magad! Hogy így kiárusítsd a becsületet! És miért? Azt hiszed, az emberek követni fognak egy árulót? Jó példa ez az ifjúságnak?",
        ["Sensei_zone3_2"] = "Válaszolj: miért akarja Sogun a halálát, és mi az a mágikus Gömb, amiről beszéltél?",
        ["Sensei_zone4_2"] = "Megmenekíteni és megállítani kell a Herceget, mielőtt megtalálja Özvegyet... és a Gömböt...",
        ["Sensei_zone5_1"] = "Együttérzek veled – őszintén. De az összetört szív rossz tanácsadó. Kérlek értsd meg: emberek szenvednek miattad.",
        ["Sensei_zone6_2"] = "Várj! Oly sok kérdésem van! Ki vagy te? Mi van odakint, a Kapuk mögött? Tudni akarom...",
        ["Wasp_zone4_3"] = "Állj meg – alábecsültelek, öreg! Nekem a szállításért fizettek, semmi keresnivalóm nincs Özvegy becsületéért harcolni. Megmutatom a rejtekhelyét!",
        ["Wasp_zone4_4"] = "Özvegy szerette a Herceget, de az visszautasította őt. Aztán talált magának egy új játékot: Sogun-t. A banya azt a bolond hadurat használja a bosszújához.",
        ["Wasp_zone4_5"] = "Özvegy uralkodni akar a férfiakon, és egymás ellen akarja kijátszani őket. A Gömb naggyá teszi majd a kiválasztottját... és teljesen hűségessé teszi hozzá.",
        ["Widow_zone5_3"] = "Számomra nincs visszaút. Látom, hogy segíteni akarsz, de már túl késő – a Herceg már elvitte a Gömböt. Sogun megpróbálta megvédeni, de hiába.",
        ["Widow_zone5_4"] = "Sohasem láttam még a Herceget ennyire... vadnak. Lángoltak a szemei! Úgy gondolta, vicces lenne kivégezni egy árulót azon a helyen, ahol először találkoztunk. Megmutatom neked...",
        ["characterAncient"] = "ŐSI",
        ["characterSensei"] = "SENSEI",
    },
    ita = {
        ["Ancient_zone6_1"] = "Non stai sognando. Ho fermato il tempo per riportare la Sfera nell'ombra. La sua presenza qui è un errore dovuto all'instabilità del Portale delle Ombre.",
        ["Ancient_zone6_2"] = "Umano, stanno per cambiare molte cose. Ora riposa. Quando ti sveglierai, nessuno si ricorderà di te. È giusto così. Un giorno capirai...",
        ["Butcher_zone3_3"] = "Eh eh, guarda come se la dà a gambe Principe! Avresti dovuto vedere la tua faccia, vecchio. Vedi? Il tuo nuovo amico è un bugiardo e un codardo!",
        ["Butcher_zone3_4"] = "So che appena Principe tirerà le cuoia, Shogun non mi permetterà più di vivere. Sono solo uno strumento, sono sacrificabile. Quindi ti aiuterò.",
        ["Butcher_zone3_5"] = "È stata una donna a convincere Shogun che il trono gli spetta di diritto. Gli ha promesso la Sfera, di diventare un grande guerriero. A condizione di essere il suo signore.",
        ["Butcher_zone3_6"] = "Vai al porto. Shogun sta aspettando l'arrivo di una nave con la Sfera. È l'ultima possibilità per Principe di reclamare il suo trono.",
        ["Hermit_zone2_3"] = "Cerca di capire: per la nostra arte è la fine! Deve cambiare per sopravvivere. So come. E Shogun ha promesso che, se avessi addestrato i suoi uomini, mi avrebbe protetto.",
        ["Hermit_zone2_4"] = "Macellaio e la sua banda sono poco lontani. Sono stati loro a rapirti, sire. Va', spero che troverai una risposta ai tuoi interrogativi.",
        ["NAME_BUTCHER"] = "MACELLAIO",
        ["NAME_HERMIT"] = "EREMITA",
        ["NAME_PRINCE"] = "PRINCIPE",
        ["NAME_WASP"] = "VESPA",
        ["NAME_WIDOW"] = "VEDOVA",
        ["OK"] = "OK",
        ["Prince_zone1_1"] = "Grazie! Sei nobile, pochi avrebbero lottato per qualcuno che non conoscono. Pensavo fosse giunta la mia ora, perché quelle sono persone senza scrupoli.",
        ["Prince_zone1_2"] = "Ho scoperto qualcosa che non avrei dovuto sapere: un certo Eremita insegna ai miei soldati pratiche proibite. Volevano disfarsi di un testimone...",
        ["Prince_zone1_3"] = "Sono andato da lui con degli uomini per chiarire la situazione, ma mi hanno imprigionato. Per fortuna sono riuscito a fuggire.",
        ["Prince_zone2_1"] = "I MIEI uomini! Non avrei dovuto farlo capo del mio esercito... Se hai ancora solo una briciola d'onore, dicci dove si trova l'accampamento dei banditi!",
        ["Sensei_arc_outro"] = "Continua...",
        ["Sensei_zone1_1"] = "Troppe coincidenze. Qualcuno sapeva della visita e ha avvertito i banditi. È possibile che Eremita sia coinvolto? Dobbiamo scoprirlo. Andiamo!",
        ["Sensei_zone2_1"] = "Vergognati! Hai venduto il tuo onore! E per cosa? Pensi che le persone seguiranno questo traditore? Ti sembra un bell'insegnamento per i giovani?",
        ["Sensei_zone3_2"] = "Rispondimi: perché Shogun lo vuole morto e cos'è la Sfera magica di cui mi hai parlato?",
        ["Sensei_zone4_2"] = "Dobbiamo fermare Principe prima che trovi Vedova... e la Sfera...",
        ["Sensei_zone5_1"] = "Ti comprendo, davvero. Ma un cuore spezzato è un cattivo consigliere. Cerca di capire: ci sono persone che soffrono per causa tua.",
        ["Sensei_zone6_2"] = "Aspetta! Ho molte domande! Chi sei? Cosa c'è, dietro al Portale? Voglio saperlo...",
        ["Wasp_zone4_3"] = "Fermati. Ti ho sottovalutato, vecchio! Sono stata pagata per la consegna, non ho intenzione di combattere per Vedova. Ti dirò dove si nasconde!",
        ["Wasp_zone4_4"] = "Vedova era innamorata di Principe, ma lui l'ha rifiutata. Così ha trovato un nuovo giocattolo: Shogun. Quella megera lo sta usando per ottenere la sua vendetta.",
        ["Wasp_zone4_5"] = "Vedova vuole comandare gli uomini e farli combattere l'uno contro l'altro. La Sfera darà grandi poteri al suo prescelto... e lo farà ubbidire solo a lei.",
        ["Widow_zone5_3"] = "Non tornerò indietro. Vedo che vuoi aiutarmi, ma è troppo tardi: Principe ha già preso la Sfera. Shogun ha cercato di difenderla, ma invano.",
        ["Widow_zone5_4"] = "Com'era strano, Principe! I suoi occhi sembravano in fiamme! Gli piaceva l'idea di giustiziare un traditore dove ci siamo incontrati la prima volta. Lascia che te lo mostri...",
        ["characterAncient"] = "ANTICO",
        ["characterSensei"] = "SENSEI",
    },
    kor = {
        ["Ancient_zone6_1"] = "꿈이 아니라네. 내가 구를 그림자로 되돌리려고 시간을 멈췄지. 구가 이곳에 있는 건 불안정한 그림자의 문으로 빚어진 실수라네.",
        ["Ancient_zone6_2"] = "변화가 찾아올 걸세. 이제 잠을 자게. 그리고 일어나면 자네의 일은 아무도 기억하지 못할 거지. 그래야 한다네. 언젠가 자네가 이해하게 되면...",
        ["Butcher_zone3_3"] = "흐흐! 왕자가 도망치는 모습 좀 봐요! 당황했군요, 노인 양반. 당신의 새 친구는 나약한 거짓말쟁이일 뿐이에요!",
        ["Butcher_zone3_4"] = "왕자가 마지막 숨을 거두면, 쇼군은 당장 날 없애버릴 거죠. 잘못 생각했어요, 난 그저 소모품일 뿐인데. 그러니 당신을 도울게요.",
        ["Butcher_zone3_5"] = "어떤 여인이 쇼군에게 왕좌는 당연히 그의 것이라고 말했어요. 쇼군이 그 구를 갖고, 위대한 장군이 될 거라 장담했죠. 다 그 여자의 손에 놀아나서 그런 거예요.",
        ["Butcher_zone3_6"] = "항구로 가세요. 쇼군이 구를 실은 배가 오길 기다리고 있어요. 왕자가 왕좌를 되찾을 마지막 기회죠.",
        ["Hermit_zone2_3"] = "생각해 보십시오. 우리의 무술은 한계가 있습니다! 살아남으려면 변화가 필요하고, 제가 그 방법을 알고 있죠. 그리고 쇼군은 그의 부하들을 훈련시키는 조건으로 보호를 약속했습니다.",
        ["Hermit_zone2_4"] = "부쳐는 여기서 멀지 않은 곳에 일당과 함께 있습니다. 그놈들이 왕자님을 납치한 거죠. 가서 원하는 답을 찾길 바라겠습니다.",
        ["NAME_BUTCHER"] = "부쳐",
        ["NAME_HERMIT"] = "허밋",
        ["NAME_PRINCE"] = "왕자",
        ["NAME_WASP"] = "와스프",
        ["NAME_WIDOW"] = "위도우",
        ["OK"] = "확인",
        ["Prince_zone1_1"] = "감사합니다! 품격을 모르는 놈들에게 맞설 수 있는 몇 안 되는 고귀하신 분이군요. 사실 전 그 무자비한 놈들 손에 죽을 거라고 생각했거든요.",
        ["Prince_zone1_2"] = "전 의도치 않게 제 병사들이 허밋 밑에서 금지된 무술을 배우고 있다는 걸 알게 되었습니다. 그래서 그 장면을 목격한 절 없애려 하는 거죠...",
        ["Prince_zone1_3"] = "전 상황을 바로 잡으려고 병사들을 데리고 허밋을 찾아갔지만, 오히려 포로로 잡히고 말았어요. 하지만 운 좋게 탈출할 수 있었습니다.",
        ["Prince_zone2_1"] = "이런! 그를 우리 부대의 지휘관으로 앉힌 건 실수였어요... 당신에게 아직 최소한의 명예라도 남아있다면, 그 도적의 근거지를 말해요!",
        ["Sensei_arc_outro"] = "未完待續……",
        ["Sensei_zone1_1"] = "우연이 너무 많군. 누군가가 우리가 오는 걸 알고 도적에게 경고를 한 거지. 하지만 허밋은 무슨 관련이 있는 걸까? 그걸 알아내야 하네. 가세!",
        ["Sensei_zone2_1"] = "부끄러운 줄 알아야지! 그렇게 명예를 팔아넘기다니! 그리고 무엇을 위한다고? 사람들이 반역자의 말을 따를 거라고 생각하는 건가? 이게 젊은이들에게 좋은 본보기가 될 거라고 생각하는 거야?",
        ["Sensei_zone3_2"] = "대답하게, 쇼군이 왕자를 죽이려는 이유는 뭐고, 자네가 말한 마법 구는 뭐지?",
        ["Sensei_zone4_2"] = "왕자가 위도우와... 구를 찾지 못하게 해야 하네...",
        ["Sensei_zone5_1"] = "그대를 이해하네. 진심으로... 하지만 상처받은 마음은 잘못된 판단으로 이어지기 쉽지. 그대 때문에 고통 받고 있는 사람들이 있다는 걸 잊지 말게.",
        ["Sensei_zone6_2"] = "잠깐만요! 물어볼 게 많아요! 당신은 누구죠? 문 뒤에는 뭐가 있는 거죠? 알고 싶어요...",
        ["Wasp_zone4_3"] = "잠깐만요, 알겠다고요! 내가 돈을 받고 전달하긴 했지만, 위도우의 명예를 위해 싸울 생각은 없어요. 위도우의 은신처를 알려드리죠!",
        ["Wasp_zone4_4"] = "위도우는 왕자를 사랑했지만, 왕자가 거절했어요. 그러다 쇼군이라는 새 장난감을 찾은 거죠. 그 쭈그렁 할망구는 멍청한 장군을 이용해 복수를 하는 거예요.",
        ["Wasp_zone4_5"] = "위도우는 사람들을 지배하고, 한 명씩 갖고 놀고 싶어 하죠. 그 구만 있으면 엄청난 힘을 얻어... 그녀에게 완전히 복종하게 되거든요.",
        ["Widow_zone5_3"] = "날 되돌릴 방법은 없어요. 날 도와주고 싶은 것 같지만, 너무 늦었죠. 왕자가 이미 구를 가져갔거든요. 쇼군이 막으려 했지만, 헛수고였죠.",
        ["Widow_zone5_4"] = "그렇게... 거친 왕자의 모습은 처음이었어요. 눈에서 광기가 흘렀죠! 우리가 처음 만난 곳에서 반역자를 처단하는 게 재미있다고 생각했나봐요. 제가 안내해 드릴게요...",
        ["characterAncient"] = "고대인",
        ["characterSensei"] = "센세이",
    },
    por = {
        ["Ancient_zone6_1"] = "Você está delirando. Eu parei o tempo para levar a Esfera de volta às sombras. Sua presença aqui foi um erro causado pela instabilidade dos Portões das Sombras.",
        ["Ancient_zone6_2"] = "A mudança é iminente, humano. Por hora, durma. Quando acordar, ninguém se lembrará de seu feito. É assim que deve ser. Um dia, você compreenderá...",
        ["Butcher_zone3_3"] = "Hi hi! Olha só o Príncipe dando no pé! Você devia ter visto sua cara, meu velho. Sabe, seu novo amigo é um mentiroso sem escrúpulos!",
        ["Butcher_zone3_4"] = "Eu sei que, assim que o Príncipe der seu último suspiro, o Shogun não me deixará viver. Sou apenas uma ferramenta, totalmente dispensável. Então, vou ajudar você.",
        ["Butcher_zone3_5"] = "Uma mulher convenceu o Shogun de que o trono é dele por direito. Ela prometeu que ele terá a Esfera, tornando-se um grande senhor da guerra. Tudo isso por ser vassalo dela.",
        ["Butcher_zone3_6"] = "Vá até o porto. O Shogun está esperando por um navio que está trazendo a Esfera. É a última chance do Príncipe reivindicar seu trono.",
        ["Hermit_zone2_3"] = "Tente entender, nossa arte está para ser extinta! Para sobrevivermos, precisamos mudar as coisas e eu sei como. Além disso, o Shogun me prometeu proteção se eu treinasse seus homens.",
        ["Hermit_zone2_4"] = "O Açougueiro reside com sua gangue não muito longe daqui. Foram eles que o sequestraram, senhor. Vá! Espero que encontre suas respostas.",
        ["NAME_BUTCHER"] = "AÇOUGUEIRO",
        ["NAME_HERMIT"] = "EREMITA",
        ["NAME_PRINCE"] = "PRÍNCIPE",
        ["NAME_WASP"] = "VESPA",
        ["NAME_WIDOW"] = "VIUVA",
        ["OK"] = "OK",
        ["Prince_zone1_1"] = "Obrigado! Você foi muito nobre, pois poucos defenderiam alguém a quem não conhecem. Essas pessoas não conhecem misericórdia, achei que meu fim estava próximo.",
        ["Prince_zone1_2"] = "Eu descobri algo que não devia: meus soldados estudam práticas proibidas com um tal Eremita. Eles queriam acabar comigo, pois agora sou uma testemunha...",
        ["Prince_zone1_3"] = "Levei uma unidade de meus homens até ele para esclarecer as coisas, e eles me capturaram. Porém, a sorte estava ao meu lado e consegui fugir.",
        ["Prince_zone2_1"] = "MEUS homens! Colocá-lo como chefe do meu exército foi um erro... Se você ainda tiver um pingo de honra, diga-nos onde fica o acampamento desses bandidos!",
        ["Sensei_arc_outro"] = "Continua...",
        ["Sensei_zone1_1"] = "Muita coincidência. Alguém sabia de nossa visita e alertou os bandidos. Mas qual o envolvimento do Eremita? Precisamos descobrir isso. Vamos!",
        ["Sensei_zone2_1"] = "Que vergonha! Vendendo sua honra sem o menor pudor! E pelo quê? Você acha mesmo que as pessoas seguirão um traidor? Que esse é um bom exemplo para os jovens?",
        ["Sensei_zone3_2"] = "Diga-me, por que o Shogun o quer morto? E o que é essa Esfera mágica da qual você falava?",
        ["Sensei_zone4_2"] = "Devemos deter o Príncipe antes que ele encontre a Viúva... e a Esfera...",
        ["Sensei_zone5_1"] = "Eu simpatizo com você, de verdade! Mas o coração partido é um péssimo conselheiro. Entenda, por favor, que há pessoas sofrendo por sua causa.",
        ["Sensei_zone6_2"] = "Espere! Tenho tantas perguntas! Quem é você? O que há por detrás dos Portões? Eu quero saber...",
        ["Wasp_zone4_3"] = "Pare! Subestimei você, meu velho! Me pagaram para fazer a entrega, mas não para lutar pela honra da Viúva. Vou te mostrar onde ela se esconde!",
        ["Wasp_zone4_4"] = "A Viúva amava o Príncipe, mas ele a rejeitou. Então, ela encontrou um novo brinquedinho: o Shogun. A bruxa está usando aquele senhor da guerra imbecil para se vingar.",
        ["Wasp_zone4_5"] = "Ela quer governar os homens e jogá-los uns contra os outros. A Esfera vai fazer com que seu escolhido seja grandioso... e totalmente leal a ela.",
        ["Widow_zone5_3"] = "Não há volta para mim. Sei que você quer ajudar, mas é tarde demais... o Príncipe já levou a Esfera. O Shogun tentou defendê-la, mas foi em vão.",
        ["Widow_zone5_4"] = "Eu nunca vi o Príncipe tão... selvagem. Seus olhos flamejavam! Ele achou que seria divertido executar um traidor no local onde nos conhecemos. Vou mostrar a você...",
        ["characterAncient"] = "ANTIGO",
        ["characterSensei"] = "SENSEI",
    },
    rom = {
        ["Ancient_zone6_1"] = "Nu visezi. Am oprit timpul pentru a duce Sfera înapoi în umbre. Prezenţa ei aici a fost o greșeală — cauzată de instabilitatea Porţilor Umbrelor.",
        ["Ancient_zone6_2"] = "Schimbarea este iminentă, omule. Deocamdată, dormi. Când te vei trezi, nimeni nu-și va mai aminti de fapta ta. Așa trebuie să fie. Într-o zi, vei înţelege...",
        ["Butcher_zone3_3"] = "He-he! Privește-l pe Prinţ cum o ia la goană! Ar fi trebuit să-ţi vezi faţa, bătrâne. Vezi? Noul tău prieten este un mincinos lipsit de coloană vertebrală!",
        ["Butcher_zone3_4"] = "Știu că de îndată ce Prinţul își va da ultima suflare, Shogun nu mă va lăsa în viaţă. Sunt doar o unealtă — de sacrificiu. Așa că... te voi ajuta.",
        ["Butcher_zone3_5"] = "O anume femeie l-a convins pe Shogun că tronul îi aparţine de drept. I-a promis că va avea Sfera și va deveni un mare senior al războiului — totul în schimbul supunerii sale.",
        ["Butcher_zone3_6"] = "Mergi în port. Shogun așteaptă sosirea unei corăbii — cea care aduce Sfera. Este ultima șansă a Prinţului de a-și revendica tronul.",
        ["Hermit_zone2_3"] = "Încearcă să înţelegi — arta noastră a ajuns la final! Pentru a supravieţui, trebuie să se schimbe. Știu cum, iar Shogunul mi-a promis protecţie în schimbul antrenării oamenilor săi.",
        ["Hermit_zone2_4"] = "Măcelarul locuiește cu banda lui nu departe de aici. Ei au fost răpitorii tăi, sire. Du-te — fie să găsești răspunsurile pe care le cauţi.",
        ["NAME_BUTCHER"] = "MĂCELAR",
        ["NAME_HERMIT"] = "PUSTNIC",
        ["NAME_PRINCE"] = "PRINŢ",
        ["NAME_WASP"] = "VIESPE",
        ["NAME_WIDOW"] = "VĂDUVĂ",
        ["OK"] = "OK",
        ["Prince_zone1_1"] = "Îţi mulţumesc! Ești nobil — puţini ar lua apărarea cuiva pe care nu-l cunosc. Credeam că moartea e aproape — oamenii aceștia nu știu ce este mila.",
        ["Prince_zone1_2"] = "Am aflat ceva ce nu trebuia: soldaţii mei au studiat practici interzise sub îndrumarea unui anumit Sihastru. Au vrut să mă elimine ca martor...",
        ["Prince_zone1_3"] = "Am luat o unitate de oameni la el pentru a clarifica lucrurile, dar am fost luat captiv. Cu toate acestea, norocul a fost de partea mea și am reușit să scap.",
        ["Prince_zone2_1"] = "Oamenii mei! Să-l pun la conducerea armatei mele a fost o greșeală... Dacă mai aveţi măcar un strop de onoare, spuneţi-ne unde este tabăra bandiţilor!",
        ["Sensei_arc_outro"] = "Sfârșit.",
        ["Sensei_zone1_1"] = "Prea multe coincidenţe. Cineva a știut despre vizita noastră și i-a avertizat pe bandiţi. Dar cum este implicat Pustnicul? Trebuie să aflăm. Să mergem!",
        ["Sensei_zone2_1"] = "Rușine să-ţi fie! Îţi vinzi onoarea pe faţă! Și pentru ce? Crezi că oamenii vor urma un trădător? Este acesta un bun exemplu pentru cei tineri?",
        ["Sensei_zone3_2"] = "Răspunde-mi: de ce vrea Shogun să fie mort și despre ce Sferă magică vorbeai?",
        ["Sensei_zone4_2"] = "Trebuie să-l oprim pe Prinţ înainte să o găsească pe Văduvă... și Sfera...",
        ["Sensei_zone5_1"] = "Te compătimesc — chiar o fac. Dar o inimă frântă este un sfetnic slab. Te rog să înţelegi: sunt oameni care suferă din cauza ta.",
        ["Sensei_zone6_2"] = "Stai! Am atâtea întrebări! Cine ești? Ce este acolo, în spatele Porţilor? Vreau să știu...",
        ["Wasp_zone4_3"] = "Stai — te-am subestimat, moșule! Am fost plătită pentru livrare, dar nu am nicio treabă să lupt pentru onoarea Văduvei. Îţi voi arăta ascunzătoarea ei!",
        ["Wasp_zone4_4"] = "Văduva îl iubea pe Prinţ, dar el a respins-o. Apoi și-a găsit o nouă jucărie: Shogun. Cotoroanţa se folosește de acel lord al războiului stupid pentru răzbunarea ei.",
        ["Wasp_zone4_5"] = "Văduva vrea să conducă bărbaţii și să-i asmută pe unii împotriva altora. Sfera îl va face pe alesul ei măreţ... și absolut loial ei.",
        ["Widow_zone5_3"] = "Nu mai există cale de întoarcere pentru mine. Văd că vrei să mă ajuţi, dar e prea târziu — Prinţul a luat deja Sfera. Shogun a încercat să o apere, dar în zadar.",
        ["Widow_zone5_4"] = "Nu l-am văzut niciodată pe Prinţ atât de... sălbatic. Ochii lui ardeau! S-a gândit că ar fi amuzant să execute o trădătoare exact în locul în care ne-am cunoscut. Îţi voi arăta...",
        ["characterAncient"] = "ANTICUL",
        ["characterSensei"] = "SENSEI",
    },
    rus = {
        ["Ancient_zone6_1"] = "Нет. Ты не спишь. Я остановил время, чтобы забрать Сферу назад в мир Теней. Она здесь по ошибке, ибо Врата Теней в этом мире нестабильны.",
        ["Ancient_zone6_2"] = "Грядут перемены, человек. А пока — спи. Когда ты проснешься, никто не вспомнит о твоем подвиге. Так нужно. Однажды ты все поймешь...",
        ["Butcher_zone3_3"] = "Ха! Смотри, Князь пустился наутек! Видел бы ты свое лицо, старик! Понимаешь, твой новый друг — бесхребетный лжец!",
        ["Butcher_zone3_4"] = "Я понимаю, что как только Князь испустит дух, Сегун не даст мне жить. Я — просто инструмент, меня можно заменить. И потому я помогу тебе.",
        ["Butcher_zone3_5"] = "Одна женщина внушила Сегуну, что трон принадлежит ему. Она обещала вояке Сферу, что сделает его великим полководцем. В обмен на верность ей.",
        ["Butcher_zone3_6"] = "Отправляйся в порт. Сегун ждет прибытия судна. Сфера должна быть на нем. Она — это единственный шанс Князя вернуть себе трон.",
        ["Hermit_zone2_3"] = "Пойми, нашему ремеслу конец! Ему нужно меняться, чтобы выжить. Я знаю, как. И Сегун обещал мне защиту в обмен на обучение его людей.",
        ["Hermit_zone2_4"] = "Недалеко отсюда живет Мясник и его банда. Это они похитили вас, господин. Идите, желаю вам найти свои ответы.",
        ["NAME_BUTCHER"] = "МЯСНИК",
        ["NAME_HERMIT"] = "ОТШЕЛЬНИК",
        ["NAME_PRINCE"] = "КНЯЗЬ",
        ["NAME_WASP"] = "ОСА",
        ["NAME_WIDOW"] = "ВДОВА",
        ["OK"] = "ОК",
        ["Prince_zone1_1"] = "Спасибо! Ты благороден, мало кто вступится за незнакомца. Я уже был готов принять смерть, потому что эти люди не знают милосердия. ",
        ["Prince_zone1_2"] = "Я узнал то, что не должен был: мои солдаты обучаются запрещенным практикам у некого Отшельника. И меня хотели убрать как свидетеля... ",
        ["Prince_zone1_3"] = "Я собрал людей и направился к нему, чтобы все выяснить, но попал в плен. Правда, удача не отвернулась от меня — и я смог сбежать.",
        ["Prince_zone2_1"] = "Моих людей! Ставить его во главе армии было ошибкой... Если у тебя осталась хотя бы капля чести, скажи нам, где лагерь бандитов?",
        ["Sensei_arc_outro"] = "Конец.",
        ["Sensei_zone1_1"] = "Слишком много совпадений. Кто-то знал о вашем визите и предупредил разбойников. Но причем здесь Отшельник? Мы должны выяснить это. Идем!",
        ["Sensei_zone2_1"] = "Стыдись! Ты продал свою честь с потрохами! И ради чего? Думаешь, люди пойдут за предателем? Какой пример ты подаешь молодым?",
        ["Sensei_zone3_2"] = "Отвечай, почему Сегун хочет его смерти и что за магическая Сфера, о которой ты говорил?!",
        ["Sensei_zone4_2"] = "Нужно остановить Князя, пока он не нашел Вдову. А с ней — и Сферу...",
        ["Sensei_zone5_1"] = "Я сочувствую тебе, правда. Но разбитое сердце — плохой советчик. Пойми, что из-за тебя пострадали люди.",
        ["Sensei_zone6_2"] = "Постой! У меня столько вопросов! Кто ты? Что там, за вратами? Я хочу знать...",
        ["Wasp_zone4_3"] = "Стой, я недооценила тебя, старик! Мне заплатили за доставку, но драться за честь Вдовы я не обязана! Я покажу, где она скрывается!",
        ["Wasp_zone4_4"] = "Вдова любила Князя, но тот отверг ее. Она нашла себе новую игрушку — Сегуна. Чертовка использует глупого воеводу, чтобы отомстить.",
        ["Wasp_zone4_5"] = "Вдова хочет управлять мужчинами, стравливать их между собой. Сфера же сделает ее избранника великим... и полностью верным ей.",
        ["Widow_zone5_3"] = "Для меня нет пути назад. Вижу, ты хочешь помочь, но слишком поздно — Князь забрал Сферу. Сегун пытался защитить ее, но безуспешно.",
        ["Widow_zone5_4"] = "Я никогда не видела Князя таким диким. Его глаза горели! Он посчитал забавным казнить предателя на месте нашей первой встречи. Я покажу...",
        ["characterAncient"] = "ДРЕВНИЙ",
        ["characterSensei"] = "СЭНСЕЙ",
    },
    spa = {
        ["Ancient_zone6_1"] = "No estás soñando; he parado el tiempo para llevar la esfera de vuelta a la sombra. Su presencia aquí fue un error causado por la inestabilidad de la Puerta de las Sombras.",
        ["Ancient_zone6_2"] = "El cambio es inminente, humano. Por ahora, duerme; cuando despiertes nadie recordará tu hazaña. Ha de ser así. Algún día lo comprenderás...",
        ["Butcher_zone3_3"] = "¡Ji, ji, mira cómo huye el príncipe! Tendrías que haberte visto la cara, anciano. Mira: ¡tu nuevo amigo es un mentiroso pusilánime!",
        ["Butcher_zone3_4"] = "Sé que, en cuanto el príncipe exhale su último aliento, el Shogun no permitirá que yo viva. No soy más que una herramienta; soy prescindible. Por eso, te ayudaré.",
        ["Butcher_zone3_5"] = "Cierta mujer convenció al Shogun de que el trono es legítimamente suyo. Le prometió que tendría la esfera y se convertiría en un gran señor de la guerra. Todo eso por ser su señor feudal.",
        ["Butcher_zone3_6"] = "Ve al puerto. El Shogun aguarda que llegue un barco con la esfera; es la última oportunidad del príncipe de recuperar su trono.",
        ["Hermit_zone2_3"] = "Trata de entenderlo: ¡nuestro arte se esfuma! Para sobrevivir, necesita cambiar. Y yo sé cómo hacerlo. Además, el Shogun me prometió protección a cambio de adiestrar a sus hombres.",
        ["Hermit_zone2_4"] = "El Carnicero vive con su banda a poca distancia de aquí. Fueron tus captores, además. Ve: deseo que des con tus respuestas.",
        ["NAME_BUTCHER"] = "CARNICERO",
        ["NAME_HERMIT"] = "ERMITAÑO",
        ["NAME_PRINCE"] = "PRÍNCIPE",
        ["NAME_WASP"] = "AVISPA",
        ["NAME_WIDOW"] = "VIUDA",
        ["OK"] = "VALE",
        ["Prince_zone1_1"] = "¡Gracias! Eres noble, pues pocos defenderían a alguien a quien no conocen. Pensaba que la muerte me acechaba, porque esa gente no conoce la piedad.",
        ["Prince_zone1_2"] = "Me enteré de algo que no debía saber: mis soldados estudian prácticas prohibidas bajo un tal Ermitaño. Querían eliminarme como testigo...",
        ["Prince_zone1_3"] = "Llevé una unidad de mis hombres hasta él para aclarar las cosas, pero me tomaron prisionero. Sin embargo, la suerte siguió de mi lado y logré huir.",
        ["Prince_zone2_1"] = "¡Son mis hombres, no los suyos! Ponerlo al frente de mi ejército fue un error... ¡Si te queda aunque solo sea un ápice de honor, dinos dónde está el campamento de los bandidos!",
        ["Sensei_arc_outro"] = "Continuará...",
        ["Sensei_zone1_1"] = "Demasiadas coincidencias. Alguien supo de nuestra visita y avisó a los bandidos. Pero ¿de qué modo está involucrado el Ermitaño? Hemos de averiguarlo. ¡Vamos!",
        ["Sensei_zone2_1"] = "¡Vergüenza tendría que darte! ¡Vender tu orgullo de una forma tan descarada! ¿Crees que la gente seguirá la senda de un traidor? ¿Acaso es buen ejemplo para la juventud?",
        ["Sensei_zone3_2"] = "Respóndeme: ¿por qué lo quiere muerto el Shogun, y cuál es la esfera mágica de la que hablabas?",
        ["Sensei_zone4_2"] = "Hemos de detener al príncipe antes de que encuentre a la Viuda... y la esfera.",
        ["Sensei_zone5_1"] = "Te comprendo, de verdad que sí, pero un corazón roto es mal consejero. Te ruego que trates de entenderlo: hay gente que sufre por tu culpa.",
        ["Sensei_zone6_2"] = "¡Espera, tengo muchas preguntas! ¿Quién eres? ¿Qué hay tras las puertas? Quiero saberlo...",
        ["Wasp_zone4_3"] = "Detente; ¡te he subestimado, anciano! Me han pagado por realizar la entrega, pero no tengo por qué luchar por el honor de la Viuda. Te mostraré su escondrijo.",
        ["Wasp_zone4_4"] = "La Viuda amaba al príncipe, pero este la rechazó, de modo que se buscó un juguete nuevo: el Shogun. La arpía está utilizando al estúpido señor de la guerra para vengarse.",
        ["Wasp_zone4_5"] = "La Viuda quiere gobernar a los hombres y enfrentarlos unos con otros. La esfera hará grande a su elegido..., que también será totalmente leal a ella.",
        ["Widow_zone5_3"] = "Ya no hay vuelta atrás para mí. Veo que quieres ayudar, pero es demasiado tarde; el príncipe ya se ha llevado la esfera. El Shogun trató de defenderla, pero fue en vano.",
